import string

def gen(rng):
    alpha = string.ascii_letters + string.digits
    punct = string.punctuation
    def rnd(n, p):
        parts = []
        for _ in range(n):
            if rng.random() < p:
                parts.append(rng.choice(alpha))
            elif rng.random() < 0.85:
                parts.append(rng.choice(punct))
            else:
                parts.append(' ')
        s = ''.join(parts).strip()
        if not any(c.isalnum() for c in s):
            s += 'x'
        return s
    tests = ['Hello, World! 123', 'a', '7', '!!!a!!!', '#$%^&*()_+z', 'a b  c', 'a - b', '100% sure @ 5pm - ok?',
             'abcXYZ019', 'x!y', '"quoted" text', "it's 5 o'clock", 'a\\b/c|d~e`f']
    for n in (2, 3, 5, 8, 12, 20, 40, 80, 150):
        for p in (0.2, 0.5, 0.9):
            tests.append(rnd(n, p))
    tests.append(rnd(100000, 0.5))
    tests.append(rnd(100000, 0.95))
    tests.append(rnd(100000, 0.05))
    tests.append('a' + '!' * 99998 + 'b')
    return tests
